-- J10 final read-only cohort, content and historic progress regression.
SELECT
(SELECT count(*)=22 FROM private.iclub_exam_chemistry_recheck_items_v1) AS recheck_count,
(SELECT count(DISTINCT syllabus_unit)=22 FROM private.iclub_exam_chemistry_recheck_items_v1) AS recheck_units,
(SELECT count(*)=154 FROM private.iclub_exam_chemistry_recheck_review_v1 WHERE verdict='internal_ai_pass') AS recheck_AI_gates,
(SELECT count(*)=22 FROM private.iclub_exam_chemistry_recheck_preflight_v1 WHERE seven_internal_AI_reviews AND different_from_entry_stem AND different_from_P1_stem AND unreleased_no_mastery) AS recheck_preflight,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_recheck_items_v1 WHERE can_credit_mastery OR can_issue_learner OR can_be_entry_question OR can_be_P1_paper) AS recheck_never_mastery,
(SELECT count(*)=10 FROM private.iclub_exam_chemistry_recheck_revisions_v1) AS recheck_editorial_versions_preserved,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_recheck_attempts_v1) AS recheck_attempts_empty,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_recheck_release_items_v1) AS recheck_approvals_empty,
(SELECT enabled=false AND owner_go_at IS NULL FROM private.iclub_exam_chemistry_recheck_control_v1 WHERE id=1) AS recheck_off,
NOT private.iclub_exam_chemistry_recheck_manifest_ok_v1() AS recheck_manifest_not_ready,
NOT private.iclub_exam_chemistry_recheck_student_authorized_v1() AS recheck_student_denied,
public.get_my_exam_prep_chemistry_recheck_shell_v1('ru')='{}'::jsonb AS recheck_shell_ru_off,
public.get_my_exam_prep_chemistry_recheck_shell_v1('uz')='{}'::jsonb AS recheck_shell_uz_off,
public.get_my_exam_prep_chemistry_recheck_shell_v1('en')='{}'::jsonb AS recheck_shell_en_off,
(SELECT count(*)=22 FROM private.iclub_exam_chemistry_entry_items_v1) AS entry_sources_unchanged,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_entry_attempts_v1) AS entry_attempts_empty,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_entry_shadow_v1) AS entry_shadow_attempts_empty,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_entry_release_items_v1) AS entry_release_empty,
(SELECT enabled=false FROM private.iclub_exam_chemistry_entry_release_v1 WHERE id=1) AS entry_beta_off,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_p1_beta_members_v1) AS chemistry_beta_members_empty,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_p1_live_attempts_v1) AS chemistry_p1_attempts_empty,
(SELECT enabled=false FROM private.iclub_exam_chemistry_p1_beta_control_v1 WHERE id=1) AS chemistry_p1_beta_off,
(SELECT status='draft' AND launch_enabled=false FROM private.iclub_exam_core_programs_v1 WHERE program_key='chemistry_9701') AS chemistry_program_off,
(SELECT visible_to_learners=false AND active_version IS NULL FROM private.iclub_subject_library WHERE subject_key='chemistry') AS chemistry_theory_off,
(SELECT count(*)=45 FROM private.iclub_exam_core_chemistry_p1_secure_drafts_v1) AS preserved_p1_45,
(SELECT count(*)=26 FROM private.iclub_exam_core_chemistry_p1_quarantine_v1) AS preserved_old_26,
(SELECT count(*)=40 FROM private.iclub_exam_core_chemistry_p1_mock_blueprint_preview_v1 WHERE planning_role='proposed_form') AS preserved_p1_40,
(SELECT count(*)=4 FROM private.iclub_exam_core_chemistry_p1_mock_blueprint_preview_v1 WHERE planning_role='proposed_reserve') AS preserved_p1_reserve_4,
(SELECT count(*)>=544 FROM private.exam_prep_sessions) AS math_sessions_safe,
(SELECT count(*)>=1979 FROM private.exam_prep_responses) AS math_responses_safe,
(SELECT count(*)>=502 FROM public.practice_attempts) AS practice_attempts_safe,
(SELECT count(*)>=4816 FROM public.practice_answers) AS practice_answers_safe,
(SELECT count(*)>=1 FROM private.iclub_exam_native_mcq_attempts_v1) AS economics_attempt_safe,
(SELECT count(*)>=2098 FROM public.user_subjects) AS user_subjects_safe,
(SELECT bool_and(c.relrowsecurity AND c.relforcerowsecurity) FROM pg_class c WHERE c.oid IN ('private.iclub_exam_chemistry_recheck_control_v1'::regclass,'private.iclub_exam_chemistry_recheck_release_items_v1'::regclass,'private.iclub_exam_chemistry_recheck_attempts_v1'::regclass)) AS recheck_tables_forced_rls,
NOT has_table_privilege('authenticated','private.iclub_exam_chemistry_recheck_items_v1','SELECT') AND NOT has_table_privilege('authenticated','private.iclub_exam_chemistry_recheck_attempts_v1','SELECT') AND NOT has_table_privilege('authenticated','private.iclub_exam_chemistry_recheck_release_items_v1','SELECT') AS no_direct_auth_reads,
NOT has_function_privilege('anon','public.iclub_exam_chemistry_recheck_start_v1(text,uuid,boolean)','EXECUTE') AND NOT has_function_privilege('anon','public.iclub_exam_chemistry_recheck_get_v1(uuid,text)','EXECUTE') AND NOT has_function_privilege('anon','public.iclub_exam_chemistry_recheck_review_v1(uuid,text)','EXECUTE') AS no_anon_recheck_rpc,
has_function_privilege('authenticated','public.iclub_exam_chemistry_recheck_start_v1(text,uuid,boolean)','EXECUTE') AND has_function_privilege('authenticated','public.iclub_exam_chemistry_recheck_answer_v1(uuid,integer,integer)','EXECUTE') AND has_function_privilege('authenticated','public.iclub_exam_chemistry_recheck_finish_v1(uuid)','EXECUTE') AS auth_recheck_rpc_gated,
NOT has_function_privilege('authenticated','private.iclub_exam_chemistry_recheck_manifest_ok_v1()','EXECUTE') AND NOT has_function_privilege('authenticated','private.iclub_exam_chemistry_recheck_student_authorized_v1()','EXECUTE') AS private_helpers_unexposed,
(SELECT count(*)=1 FROM pg_indexes WHERE schemaname='private' AND indexname='chemistry_recheck_one_active_per_user_v1') AS no_parallel_recheck_attempts,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_recheck_review_v1 q JOIN private.iclub_exam_chemistry_recheck_items_v1 d ON d.id=q.item_id WHERE q.snapshot_md5<>d.item_md5) AS recheck_snapshot_hash_valid;